(426, 28, 'en', 'Project Assign Member', '<p><strong>Hi</strong> {project_user}</p>\n                    <p><b>Project Name</b>&nbsp;: {project_name}</p>\n                    <p><b>Start Date&nbsp;</b>: {project_start_date}</p>\n                    <p><b>End Date&nbsp;</b>: {project_end_date}</p>\n                    <p><b>Estimated Hours&nbsp;</b>: {hours}</p>\n                    <p>Looking forward to hear from you.</p>\n                    <p><strong>Kind Regards, </strong></p>\n                    <p>{company_name}</p>', '2024-11-05 01:04:25', '2024-11-05 01:04:25'),
(427, 28, 'es', 'Project Assign Member', '<p><strong>Hi.</strong> {project_user}</p>\n                    <p><b>Nombre del proyecto</b>&nbsp;: {project_name}</p>\n                    <p><b>Fecha de inicio&nbsp;</b>: {project_start_date}</p>\n                    <p><b>Fecha final&nbsp;</b>: {project_end_date}</p>\n                    <p><b>Horas estimadas&nbsp;</b>: {hours}</p>\n                    <p>Con ganas de escuchar de usted. </p>\n                    <p><strong>Bondadoso, </strong></p>\n                    <p>{company_name}</p>', '2024-11-05 01:04:25', '2024-11-05 01:04:25'),
(428, 28, 'fr', 'Project Assign Member', '<p><strong>Salut</strong> {project_user}</p>\n                    <p><b>Nom du projet</b>&nbsp;: {project_name}</p>\n                    <p><b>Date de début&nbsp;</b>: {project_start_date}</p>\n                    <p><b>Date de fin&nbsp;</b>: {project_end_date}</p>\n                    <p><b>Heures estimées&nbsp;</b>: {hours}</p>\n                    <p>Regard sur lavenir.</p>\n                    <p><strong>Cordialement, </strong></p>\n                    <p>{company_name}</p>', '2024-11-05 01:04:25', '2024-11-05 01:04:25'),
(429, 28, 'he', 'Project Assign Member', '<p><strong>היי</strong> {project_user}</p>\n                    <p><b>שם הפרויקט</b>&nbsp;: {project_name}</p>\n                    <p><b>תאריך התחלה&nbsp;</b>: {project_start_date}</p>\n                    <p><b>תאריך סיום&nbsp;</b>: {project_end_date}</p>\n                    <p><b>שעות משוערות&nbsp;</b>: {hours}</p>\n                    <p>מצפה לשמוע ממך.</p>\n                    <p><strong>די. די. די. </strong></p>\n                    <p>{company_name}</p>', '2024-11-05 01:04:25', '2024-11-05 01:04:25'),
(430, 28, 'it', 'Project Assign Member', '<p><strong>Ciao</strong> {project_user}</p>\n                    <p><b>Nome del progetto</b>&nbsp;: {project_name}</p>\n                    <p><b>Data di inizio&nbsp;</b>: {project_start_date}</p>\n                    <p><b>Data di fine&nbsp;</b>: {project_end_date}</p>\n                    <p><b>Ore Stimate&nbsp;</b>: {hours}</p>\n                    <p>Non vedo lora di sentirti<br></p>\n                    <p><strong>Cordiali saluti, </strong></p>\n                    <p>{company_name}</p>', '2024-11-05 01:04:25', '2024-11-05 01:04:25'),
(431, 28, 'ja', 'Project Assign Member', '<p><strong>やあ</strong> {project_user}</p>\n                    <p><b>プロジェクト名</b>&nbsp;: {project_name}</p>\n                    <p><b>開始日&nbsp;</b>: {project_start_date}</p>\n                    <p><b>終了日&nbsp;</b>: {project_end_date}</p>\n                    <p><b>推定時間&nbsp;</b>: {hours}</p>\n                    <p>あなたから聞いて楽しみにして<.</p>\n                    <p><strong>カインド・レガード, </strong></p>\n                    <p>{company_name}</p>', '2024-11-05 01:04:25', '2024-11-05 01:04:25'),
(432, 28, 'nl', 'Project Assign Member', '<p><strong>Hallo</strong> {project_user}</p>\n                    <p><b>Projectnaam</b>&nbsp;: {project_name}</p>\n                    <p><b>Begindatum&nbsp;</b>: {project_start_date}</p>\n                    <p><b>Einddatum&nbsp;</b>: {project_end_date}</p>\n                    <p><b>Geschatte uren&nbsp;</b>: {hours}</p>\n                    <p>Naar voren komen om van u te horen.</p>\n                    <p><strong>Vriendelijke groeten, </strong></p>\n                    <p>{company_name}</p>', '2024-11-05 01:04:25', '2024-11-05 01:04:25'),
(433, 28, 'pl', 'Project Assign Member', '<p><strong>Witaj</strong> {project_user}</p>\n                    <p><b>Nazwa projektu</b>&nbsp;: {project_name}</p>\n                    <p><b>Data rozpoczęcia&nbsp;</b>: {project_start_date}</p>\n                    <p><b>Data zakończenia&nbsp;</b>: {project_end_date}</p>\n                    <p><b>Szacowane godziny&nbsp;</b>: {hours}</p>\n                    <p>Z niecierżną datą i z niecierżką na Ciebie.</p>\n                    <p><strong>Życzliwie, </strong></p>\n                    <p>{company_name}</p>', '2024-11-05 01:04:25', '2024-11-05 01:04:25'),
(434, 28, 'ru', 'Project Assign Member', '<p><strong>Привет</strong> {project_user}</p>\n                    <p><b>Имя проекта</b>&nbsp;: {project_name}</p>\n                    <p><b>Начальная дата&nbsp;</b>: {project_start_date}</p>\n                    <p><b>Конечная дата&nbsp;</b>: {project_end_date}</p>\n                    <p><b>Оценка часов&nbsp;</b>: {hours}</p>\n                    <p>нетерпением ожидаю услышать от вас.</p>\n                    <p><strong>Что касается, </strong></p>\n                    <p>{company_name}</p>', '2024-11-05 01:04:25', '2024-11-05 01:04:25');
