(435, 28, 'pt', 'Project Assign Member', '<p><strong>Oi</strong> {project_user}</p>\n                    <p><b>Nome do Projeto</b>&nbsp;: {project_name}</p>\n                    <p><b>Data de Início&nbsp;</b>: {project_start_date}</p>\n                    <p><b>Data de encerramento&nbsp;</b>: {project_end_date}</p>\n                    <p><b>Horas Estimadas&nbsp;</b>: {hours}</p>\n                    <p>Ansioso para ouvir de você.</p>\n                    <p><strong>Tipo Considera, </strong></p>\n                    <p>{company_name}</p>', '2024-11-05 01:04:25', '2024-11-05 01:04:25'),
(436, 28, 'tr', 'Project Assign Member', '<p><strong>Hi</strong> {project_user}</p>\n                    <p><b>Proje Adı</b>&nbsp;: {project_name}</p>\n                    <p><b>Başlangıç Tarihi&nbsp;</b>: {project_start_date}</p>\n                    <p><b>Bitiş Tarihi&nbsp;</b>: {project_end_date}</p>\n                    <p><b>Tahmini Saat&nbsp;</b>: {hours}</p>\n                    <p>Sizden haber bekliyorum.</p>\n                    <p><strong>Saygılarımızla, </strong></p>\n                    <p>{company_name}</p>', '2024-11-05 01:04:25', '2024-11-05 01:04:25');
