INSERT INTO `landing_page_settings` (`id`, `name`, `value`, `created_at`, `updated_at`) VALUES
(22, 'feature_of_features', '[\n  {\n    \"feature_logo\":\"1688108756-feature_logo.png\",\n    \"feature_heading\":\"Feature\",\n    \"feature_description\":\"<p>1) CRM / Customer relationship management</p><p>2) Unified interface: a single environment for all areas.</p><p>3) No-code customization and configuration: fields, forms, business rules.</p><p>4) Mobile and accessibility: mobile app, responsive design.</p>\",\n    \"feature_language\":\"en\"\n  },\n  {\n    \"feature_logo\":\"1688108756-feature_logo.png\",\n    \"feature_heading\":\"Fonctionnalité\",\n    \"feature_description\":\"<p>1) CRM / Gestion de la relation client</p><p>2) Interface unifiée : un environnement unique pour tous les domaines.</p><p>3) Personnalisation et configuration sans code : champs, formulaires, règles métier.</p><p>4) Mobile et accessibilité : application mobile, design responsive.</p>\",\n    \"feature_language\":\"fr\"\n  },\n  {\n    \"feature_logo\":\"1688108756-feature_logo.png\",\n    \"feature_heading\":\"Característica\",\n    \"feature_description\":\"<p>1) CRM / Gestión de relaciones con clientes</p><p>2) Interfaz unificada: un solo entorno para todas las áreas.</p><p>3) Personalización y configuración sin código: campos, formularios, reglas de negocio.</p><p>4) Móvil y accesibilidad: app móvil, diseño responsivo.</p>\",\n    \"feature_language\":\"es\"\n  },\n  {\n    \"feature_logo\":\"1688108756-feature_logo.png\",\n    \"feature_heading\":\"功能\",\n    \"feature_description\":\"<p>1) CRM / 客户关系管理</p><p>2) 统一界面：所有业务领域的单一操作环境。</p><p>3) 无代码自定义与配置：字段、表单、业务规则。</p><p>4) 移动端与可访问性：移动应用，响应式设计。</p>\",\n    \"feature_language\":\"zh\"\n  },\n  {\n    \"feature_logo\":\"1688108756-feature_logo.png\",\n    \"feature_heading\":\"Característica\",\n    \"feature_description\":\"<p>1) CRM/Relacionamento com clientes</p><p>2) Interface unificada: um único ambiente para todas as áreas.</p><p>3) Personalização e configuração sem código: campos, formulários, regras de negócio.</p><p>4) Mobile e acessibilidade: app para dispositivos móveis, responsivo</p>\",\n    \"feature_language\":\"pt\"\n  },\n\n  {\n    \"feature_logo\":\"1688099120-feature_logo.png\",\n    \"feature_heading\":\"Usability and Support\",\n    \"feature_description\":\"<p>1) Core / Management script</p><p>2) Finance and accounting</p><p>3) Operations and supply chain</p><p>4) HR and personnel</p><p>5) Projects and third parties</p><p>6) Support and soon community: knowledge base, tutorials, and online chat during business hours or via email</p><p>7) Updates and maintenance: update frequency, downtime, service plans.</p>\",\n    \"feature_language\":\"en\"\n  },\n  {\n    \"feature_logo\":\"1688099120-feature_logo.png\",\n    \"feature_heading\":\"Utilisabilité et Support\",\n    \"feature_description\":\"<p>1) Noyau / Script de gestion</p><p>2) Finance et comptabilité</p><p>3) Opérations et chaîne d’approvisionnement</p><p>4) RH et personnel</p><p>5) Projets et tiers</p><p>6) Support et bientôt communauté : base de connaissances, tutoriels et chat en ligne pendant les heures de bureau ou par e-mail</p><p>7) Mises à jour et maintenance : fréquence des mises à jour, temps d\'arrêt, plans de service.</p>\",\n    \"feature_language\":\"fr\"\n  },\n  {\n    \"feature_logo\":\"1688099120-feature_logo.png\",\n    \"feature_heading\":\"Usabilidad y Soporte\",\n    \"feature_description\":\"<p>1) Núcleo / Script de gestión</p><p>2) Finanzas y contabilidad</p><p>3) Operaciones y cadena de suministro</p><p>4) RRHH y personal</p><p>5) Proyectos y terceros</p><p>6) Soporte y pronto comunidad: base de conocimientos, tutoriales y chat en línea en horario laboral o por correo electrónico</p><p>7) Actualizaciones y mantenimiento: frecuencia de actualizaciones, tiempo de inactividad, planes de servicio.</p>\",\n    \"feature_language\":\"es\"\n  },\n  {\n    \"feature_logo\":\"1688099120-feature_logo.png\",\n    \"feature_heading\":\"可用性与支持\",\n    \"feature_description\":\"<p>1) 核心 / 管理系统</p><p>2) 财务与会计</p><p>3) 运营与供应链</p><p>4) 人力资源与人员管理</p><p>5) 项目与第三方</p><p>6) 支持及即将推出的社区：知识库、教程及工作时间在线聊天或电子邮件支持</p><p>7) 更新与维护：更新频率、停机时间、服务计划。</p>\",\n    \"feature_language\":\"zh\"\n  },\n  {\n    \"feature_logo\":\"1688099120-feature_logo.png\",\n    \"feature_heading\":\"Usabilidade e suporte\",\n    \"feature_description\":\"<p>1) Core/Script de gestão</p><p>2) Finanças e contabilidade</p><p>3) Operações e cadeia de suprimentos</p><p>4) RH e pessoal</p><p>5) Projetos e terceiros</p><p>6) Suporte e brevemente comunidade: base de conhecimento, tutoriais e chat online durante as horas normais de expediente ou por e-mail</p><p>7) Atualizações e manutenção: frequência de atualizações, downtime, planos de serviço.</p>\",\n    \"feature_language\":\"pt\"\n  },\n\n  {\n    \"feature_logo\":\"1688099197-feature_logo.png\",\n    \"feature_heading\":\"Integration\",\n    \"feature_description\":\"<p>1) Native integrations: connectors for e-commerce, marketplaces, payment gateways, logistics</p><p>2) APIs and webhooks: for customizations and integration with external services</p><p>3) Reports and BI: dashboards, KPIs, real-time data analysis.</p><p>4) Security and compliance: access control, multi-factor authentication, audit logs.</p><p>5) Scalability: multi-company, multi-language/currency, cloud hosting.</p>\",\n    \"feature_language\":\"en\"\n  },\n  {\n    \"feature_logo\":\"1688099197-feature_logo.png\",\n    \"feature_heading\":\"Intégration\",\n    \"feature_description\":\"<p>1) Intégrations natives : connecteurs pour e-commerce, marketplaces, passerelles de paiement, logistique</p><p>2) APIs et webhooks : pour personnalisations et intégrations avec des services externes</p><p>3) Rapports et BI : tableaux de bord, KPI, analyse de données en temps réel.</p><p>4) Sécurité et conformité : contrôle d’accès, authentification multifacteur, journaux d’audit.</p><p>5) Évolutivité : multi-entreprise, multi-langue/devise, hébergement cloud.</p>\",\n    \"feature_language\":\"fr\"\n  },\n  {\n    \"feature_logo\":\"1688099197-feature_logo.png\",\n    \"feature_heading\":\"Integración\",\n    \"feature_description\":\"<p>1) Integraciones nativas: conectores para comercio electrónico, marketplaces, pasarelas de pago, logística</p><p>2) APIs y webhooks: para personalizaciones e integración con servicios externos</p><p>3) Informes y BI: paneles, KPIs, análisis de datos en tiempo real.</p><p>4) Seguridad y cumplimiento: control de acceso, autenticación multifactor, registros de auditoría.</p><p>5) Escalabilidad: multiempresa, multidioma/moneda, alojamiento en la nube.</p>\",\n    \"feature_language\":\"es\"\n  },\n  {\n    \"feature_logo\":\"1688099197-feature_logo.png\",\n    \"feature_heading\":\"集成\",\n    \"feature_description\":\"<p>1) 原生集成：电商、市场平台、支付网关、物流连接器</p><p>2) APIs 和 Webhooks：用于定制和与外部服务集成</p><p>3) 报告与 BI：仪表盘、KPI、实时数据分析。</p><p>4) 安全与合规：访问控制、多因素认证、审计日志。</p><p>5) 可扩展性：多公司、多语言/货币、云托管。</p>\",\n    \"feature_language\":\"zh\"\n  },\n  {\n    \"feature_logo\":\"1688099197-feature_logo.png\",\n    \"feature_heading\":\"Integração\",\n    \"feature_description\":\"<p>1) Integrações nativas: conectores para e-commerce, marketplaces, gateways de pagamento, logística</p><p>2) APIs e webhooks: para customizações e integrações com serviços externos</p><p>3) Relatórios e BI: dashboards, KPIs, análise de dados em tempo real.</p><p>4) Segurança e conformidade: controle de acesso, autenticação multifator, logs de auditoria.</p><p>5) Escalabilidade: multi-empresa, multi-idioma/moedas, hospedagem em nuvem.</p>\",\n    \"feature_language\":\"pt\"\n  }\n]', '2024-11-05 01:04:23', '2026-01-28 05:24:24'),
(23, 'highlight_feature_heading', '{\"pt\":\"ERP SaaS Tudo em Um Painel de Controlo ERP para Projetos\",\"en\":\"ERP SaaS All-in-One ERP Control Panel for Projects\",\"fr\":\"ERP SaaS Tout-en-un Panneau de Contr\\u00f4le ERP pour Projets\",\"es\":\"ERP SaaS Todo en Uno Panel de Control ERP para Proyectos\",\"zh\":\"ERP SaaS \\u4e00\\u4f53\\u5316\\u9879\\u76eeERP\\u63a7\\u5236\\u9762\\u677f\"}', '2024-11-05 01:04:23', '2026-01-28 05:39:19'),
(24, 'highlight_feature_description', '{\"pt\":\"Gest\\u00e3o de projetos: or\\u00e7amentos, aloca\\u00e7\\u00e3o de recursos, cronogramas. e muito mais...\",\"en\":\"Project management: budgets, resource allocation, timelines, and much more...\",\"fr\":\"Gestion de projets : budgets, allocation des ressources, calendriers et bien plus encore...\",\"es\":\"Gesti\\u00f3n de proyectos: presupuestos, asignaci\\u00f3n de recursos, cronogramas y mucho m\\u00e1s...\",\"zh\":\"\\u9879\\u76ee\\u7ba1\\u7406\\uff1a\\u9884\\u7b97\\u3001\\u8d44\\u6e90\\u5206\\u914d\\u3001\\u65f6\\u95f4\\u8868\\u7b49\\u7b49...\"}', '2024-11-05 01:04:23', '2026-01-28 05:39:07'),
(25, 'highlight_feature_image', '{\"pt\":\"highlight_feature_image.png\",\"en\":\"highlight_feature_image.png\",\"fr\":\"highlight_feature_image.png\",\"es\":\"highlight_feature_image.png\",\"zh\":\"highlight_feature_image.png\"}', '2024-11-05 01:04:23', '2024-11-05 01:04:23'),
(26, 'other_features', '[{\"other_features_image\":\"1761757765-other_features_image.png\",\"other_features_heading\":\"PAINEL DE CONTROLO PARA POS 12\",\"other_featured_description\":\"<p>Um sistema de ponto de venda intuitivo que suporta filiais. Pode ser utilizado em telem\\u00f3veis, tablets e ambiente Windows.<\\/p>\",\"other_feature_buy_now_link\":\"\\/register/\\pt\",\"other_features_language\":\"pt\"},{\"other_features_image\":\"1761757765-other_features_image.png\",\"other_features_heading\":\"POS CONTROL PANEL\",\"other_featured_description\":\"<p>An intuitive point-of-sale system that supports branches. Can be used on mobile phones, tablets, and Windows environments.<\\/p>\",\"other_feature_buy_now_link\":\"\\/register/\\en\",\"other_features_language\":\"en\"},{\"other_features_image\":\"1761757765-other_features_image.png\",\"other_features_heading\":\"PANNEAU DE CONTR\\u00d4LE POS\",\"other_featured_description\":\"<p>Un syst\\u00e8me de point de vente intuitif qui prend en charge les succursales. Utilisable sur mobiles, tablettes et Windows.<\\/p>\",\"other_feature_buy_now_link\":\"\\/register/\\fr\",\"other_features_language\":\"fr\"},{\"other_features_image\":\"1761757765-other_features_image.png\",\"other_features_heading\":\"PANEL DE CONTROL POS\",\"other_featured_description\":\"<p>Un sistema de punto de venta intuitivo que admite sucursales. Puede utilizarse en m\\u00f3viles, tablets y entornos Windows.<\\/p>\",\"other_feature_buy_now_link\":\"\\/register/\\es\",\"other_features_language\":\"es\"},{\"other_features_image\":\"1761757765-other_features_image.png\",\"other_features_heading\":\"POS \\u63a7\\u5236\\u9762\\u677f\",\"other_featured_description\":\"<p>\\u652f\\u6301\\u5206\\u652f\\u673a\\u6784\\u7684\\u76f4\\u89c2\\u9500\\u552e\\u70b9\\u7cfb\\u7edf\\u3002\\u53ef\\u5728\\u624b\\u673a\\u3001\\u5e73\\u677f\\u548c Windows \\u73af\\u5883\\u4e2d\\u4f7f\\u7528\\u3002<\\/p>\",\"other_feature_buy_now_link\":\"\\/register/\\zh\",\"other_features_language\":\"zh\"},{\"other_features_image\":\"1761758251-other_features_image.png\",\"other_features_heading\":\"PAINEL DE CONTROLO PARA CONTABILIDADE\",\"other_featured_description\":\"<p>Com o POC 100% Mo\\u00e7ambicano, integra-se facilmente com Gest\\u00e3o Projetos, RH, CRM e POS (Ponto de Venda).<\\/p>\",\"other_feature_buy_now_link\":\"\\/register/\\pt\",\"other_features_language\":\"pt\"},{\"other_features_image\":\"1761758251-other_features_image.png\",\"other_features_heading\":\"ACCOUNTING CONTROL PANEL\",\"other_featured_description\":\"<p>With the 100% Mozambican POC, it integrates easily with Project Management, HR, CRM, and POS.<\\/p>\",\"other_feature_buy_now_link\":\"\\/register/\\en\",\"other_features_language\":\"en\"},{\"other_features_image\":\"1761758251-other_features_image.png\",\"other_features_heading\":\"PANNEAU DE CONTR\\u00d4LE POUR LA COMPTABILIT\\u00c9\",\"other_featured_description\":\"<p>Avec le POC 100% mozambicain, il s\\u2019int\\u00e8gre facilement avec la gestion de projets, RH, CRM et POS.<\\/p>\",\"other_feature_buy_now_link\":\"\\/register/\\fr\",\"other_features_language\":\"fr\"},{\"other_features_image\":\"1761758251-other_features_image.png\",\"other_features_heading\":\"PANEL DE CONTROL PARA CONTABILIDAD\",\"other_featured_description\":\"<p>Con el POC 100% mozambique\\u00f1o, se integra f\\u00e1cilmente con Gesti\\u00f3n de Proyectos, RRHH, CRM y POS.<\\/p>\",\"other_feature_buy_now_link\":\"\\/register/\\es\",\"other_features_language\":\"es\"},{\"other_features_image\":\"1761758251-other_features_image.png\",\"other_features_heading\":\"\\u4f1a\\u8ba1\\u63a7\\u5236\\u9762\\u677f\",\"other_featured_description\":\"<p>\\u91c7\\u7528 100% \\u83ab\\u6851\\u6bd4\\u514b\\u672c\\u5730 POC\\uff0c\\u53ef\\u8f7b\\u677e\\u4e0e\\u9879\\u76ee\\u7ba1\\u7406\\u3001\\u4eba\\u529b\\u8d44\\u6e90\\u3001CRM \\u548c POS \\u96c6\\u6210\\u3002<\\/p>\",\"other_feature_buy_now_link\":\"\\/register/\\zh\",\"other_features_language\":\"zh\"}]', '2024-11-05 01:04:23', '2026-01-28 05:49:06'),
(27, 'discover_status', '{\"zh\":\"on\",\"pt\":\"on\",\"en\":\"on\",\"es\":\"on\",\"fr\":\"on\"}', '2024-11-05 01:04:23', '2026-01-28 06:18:23'),
(28, 'discover_heading', '{\"pt\":\"ERP SaaS Tudo em Um para Empresas com Gest\\u00e3o de Projetos, Contabilidade, RH, CRM e POS (Ponto de Venda).\",\"en\":\"All-in-One ERP SaaS for Companies with Project Management, Accounting, HR, CRM, and POS (Point of Sale).\",\"fr\":\"ERP SaaS tout-en-un pour les entreprises avec gestion de projets, comptabilit\\u00e9, RH, CRM et POS (point de vente).\",\"es\":\"ERP SaaS Todo en Uno para Empresas con Gesti\\u00f3n de Proyectos, Contabilidad, RRHH, CRM y POS (Punto de Venta).\",\"zh\":\"\\u9762\\u5411\\u4f01\\u4e1a\\u7684\\u5168\\u80fdERP SaaS\\uff0c\\u6db5\\u76d6\\u9879\\u76ee\\u7ba1\\u7406\\u3001\\u4f1a\\u8ba1\\u3001\\u4eba\\u529b\\u8d44\\u6e90\\u3001CRM\\u548c\\u9500\\u552e\\u70b9(POS)\\u3002\"}', '2024-11-05 01:04:23', '2026-01-28 06:21:48'),
(29, 'discover_description', '{\"pt\":\"Agora, mais do que nunca, basta um clique para viajar em primeira classe utilizando a nossa aplica\\u00e7\\u00e3o 360.\",\"en\":\"Now, more than ever, just one click to travel first-class using our 360 application.\",\"fr\":\"Aujourd\'hui plus que jamais, un seul clic pour voyager en premi\\u00e8re classe avec notre application 360.\",\"es\":\"Ahora, m\\u00e1s que nunca, solo un clic para viajar en primera clase usando nuestra aplicaci\\u00f3n 360.\",\"zh\":\"\\u73b0\\u5728\\uff0c\\u53ea\\u9700\\u4e00\\u6b21\\u70b9\\u51fb\\uff0c\\u5373\\u53ef\\u4f7f\\u7528\\u6211\\u4eec\\u7684360\\u5e94\\u7528\\u4eab\\u53d7\\u5934\\u7b49\\u8231\\u65c5\\u884c\\u4f53\\u9a8c\\u3002\"}', '2024-11-05 01:04:23', '2026-01-28 06:21:48'),
(30, 'discover_live_demo_link', '{\"pt\":\"\\/login\\/pt\",\"en\":\"\\/login\\/en\",\"fr\":\"\\/login\\/fr\",\"es\":\"\\/login\\/es\",\"zh\":\"\\/login\\/zh\"}', '2024-11-05 01:04:23', '2026-01-28 06:21:56'),
