(36, 'screenshots', '[\n    {\"screenshots\":\"1733207977-screenshots.png\",\"screenshots_heading\":\"Balanço Patrimonial\",\"screenshots_language\":\"pt\"},\n    {\"screenshots\":\"1733207977-screenshots.png\",\"screenshots_heading\":\"Balance Sheet\",\"screenshots_language\":\"en\"},\n    {\"screenshots\":\"1733207977-screenshots.png\",\"screenshots_heading\":\"Bilan Patrimonial\",\"screenshots_language\":\"fr\"},\n    {\"screenshots\":\"1733207977-screenshots.png\",\"screenshots_heading\":\"Balance General\",\"screenshots_language\":\"es\"},\n    {\"screenshots\":\"1733207977-screenshots.png\",\"screenshots_heading\":\"资产负债表\",\"screenshots_language\":\"zh\"},\n\n    {\"screenshots\":\"1733208040-screenshots.png\",\"screenshots_heading\":\"Plano Orçamental\",\"screenshots_language\":\"pt\"},\n    {\"screenshots\":\"1733208040-screenshots.png\",\"screenshots_heading\":\"Budget Plan\",\"screenshots_language\":\"en\"},\n    {\"screenshots\":\"1733208040-screenshots.png\",\"screenshots_heading\":\"Plan Budgétaire\",\"screenshots_language\":\"fr\"},\n    {\"screenshots\":\"1733208040-screenshots.png\",\"screenshots_heading\":\"Plan Presupuestario\",\"screenshots_language\":\"es\"},\n    {\"screenshots\":\"1733208040-screenshots.png\",\"screenshots_heading\":\"预算计划\",\"screenshots_language\":\"zh\"},\n\n    {\"screenshots\":\"1733208094-screenshots.png\",\"screenshots_heading\":\"Ofertas CRM\",\"screenshots_language\":\"pt\"},\n    {\"screenshots\":\"1733208094-screenshots.png\",\"screenshots_heading\":\"CRM Offers\",\"screenshots_language\":\"en\"},\n    {\"screenshots\":\"1733208094-screenshots.png\",\"screenshots_heading\":\"Offres CRM\",\"screenshots_language\":\"fr\"},\n    {\"screenshots\":\"1733208094-screenshots.png\",\"screenshots_heading\":\"Ofertas de CRM\",\"screenshots_language\":\"es\"},\n    {\"screenshots\":\"1733208094-screenshots.png\",\"screenshots_heading\":\"CRM 优惠\",\"screenshots_language\":\"zh\"},\n\n    {\"screenshots\":\"1733208208-screenshots