(21, 2, 'en', 'Deal converted through lead {lead_user_name}', '{\n                    \"Company Name\": \"user_name\",\n                    \"Lead User Name\": \"lead_user_name\",\n                    \"Lead Name\": \"lead_name\",\n                    \"Lead Email\": \"lead_email\"\n                    }', 1, '2024-11-05 01:04:22', '2024-11-05 01:04:22'),
(22, 2, 'es', 'Trato convertido a través del cliente potencial {lead_user_name}', '{\n                    \"Company Name\": \"user_name\",\n                    \"Lead User Name\": \"lead_user_name\",\n                    \"Lead Name\": \"lead_name\",\n                    \"Lead Email\": \"lead_email\"\n                    }', 1, '2024-11-05 01:04:22', '2024-11-05 01:04:22'),
